// GET /users/{id} implemented with Chi (pure net/http types).
package main

import (
	"fmt"
	"net/http"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
)

func main() {
	r := chi.NewRouter()
	r.Use(middleware.Logger) // standard func(http.Handler) http.Handler
	// handler is a normal net/http handler
	r.Get("/users/{id}", func(w http.ResponseWriter, req *http.Request) {
		id := chi.URLParam(req, "id") // read the path param
		fmt.Fprintf(w, "user %s", id)
	})
	http.ListenAndServe(":8080", r) // r is an http.Handler
}

// The SAME GET /users/:id route, now in Gin.
package main

import "github.com/gin-gonic/gin"

func main() {
	r := gin.Default() // includes Logger + Recovery middleware
	// handler receives a *gin.Context, NOT (w, r)
	r.GET("/users/:id", func(c *gin.Context) {
		id := c.Param("id") // Gin's own param accessor
		c.String(200, "user %s", id) // Gin's response helpers
	})
	r.Run(":8080") // Gin owns the server lifecycle
}

// The SAME route in Echo — handlers return an error.
package main

import (
	"net/http"

	"github.com/labstack/echo/v4"
	"github.com/labstack/echo/v4/middleware"
)

func main() {
	e := echo.New()
	e.Use(middleware.Logger()) // Echo's own middleware type
	// handler returns an error; Echo maps it to a response
	e.GET("/users/:id", func(c echo.Context) error {
		id := c.Param("id")
		return c.String(http.StatusOK, "user "+id)
	})
	e.Start(":8080")
}

// The SAME route in Fiber — note: NO net/http types anywhere.
package main

import "github.com/gofiber/fiber/v2"

func main() {
	app := fiber.New()
	// handler receives a *fiber.Ctx backed by fasthttp.RequestCtx
	app.Get("/users/:id", func(c *fiber.Ctx) error {
		id := c.Params("id")
		return c.SendString("user " + id) // fasthttp buffer, not http.ResponseWriter
	})
	app.Listen(":8080") // fasthttp server, not http.Server
}

// Why a stdlib middleware CANNOT wrap a Fiber handler.

// Standard middleware speaks net/http:
func StdLogging(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// ... needs *http.Request and http.ResponseWriter
		next.ServeHTTP(w, r)
	})
}

// Fiber gives you *fiber.Ctx (fasthttp), not (w, r):
//   app.Use(func(c *fiber.Ctx) error { ... })
// There is NO http.Request/http.ResponseWriter to hand to StdLogging,
// so the whole net/http middleware ecosystem is off-limits.
// fasthttp also REUSES c across requests: never store c or c.Body()
// beyond the handler, or you read another request's memory.

// The SAME GET /users/{id} route with ZERO dependencies (Go 1.22+).
package main

import (
	"fmt"
	"net/http"
)

func main() {
	mux := http.NewServeMux()
	// method + wildcard pattern, no third-party router
	mux.HandleFunc("GET /users/{id}", func(w http.ResponseWriter, r *http.Request) {
		id := r.PathValue("id") // Go 1.22 path value
		fmt.Fprintf(w, "user %s", id)
	})
	http.ListenAndServe(":8080", mux) // mux is a plain http.Handler
}

