// --- Chi: still net/http types, thin router on top ---
r := chi.NewRouter()
r.Get("/users/{id}", func(w http.ResponseWriter, req *http.Request) {
	fmt.Fprintf(w, "user %s", chi.URLParam(req, "id"))
})

// --- Gin: its own *gin.Context (net/http underneath) ---
g := gin.Default()
g.GET("/users/:id", func(c *gin.Context) {
	c.String(200, "user %s", c.Param("id"))
})

// --- Fiber: *fiber.Ctx, backed by fasthttp (NOT net/http) ---
app := fiber.New()
app.Get("/users/:id", func(c *fiber.Ctx) error {
	return c.SendString("user " + c.Params("id"))
})

// A plain net/http middleware.
func Logging(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		log.Printf("%s %s %s", r.Method, r.URL.Path, time.Since(start))
	})
}

// Stdlib mux: wrap directly.
var h http.Handler = Logging(mux) // works

// Chi: register with the standard signature.
r := chi.NewRouter()
r.Use(Logging) // works: Chi middleware IS func(http.Handler) http.Handler

// Gin: only via an adapter, and it breaks *gin.Context flow.
// g.Use(func(c *gin.Context) { Logging(...).ServeHTTP(c.Writer, c.Request); c.Next() }) // awkward

// Fiber: impossible. There is no *http.Request / http.ResponseWriter.
// app.Use(Logging) // does NOT compile: fasthttp has no http.Handler

// BUG (Fiber/fasthttp): the byte slice is reused after the handler returns.
var lastBody []byte
app.Post("/save", func(c *fiber.Ctx) error {
	lastBody = c.Body() // fasthttp buffer — REUSED by the next request!
	go process(lastBody) // later reads someone else's request bytes
	return c.SendStatus(200)
})

// FIX: copy out of the pooled buffer before it is reused.
app.Post("/save", func(c *fiber.Ctx) error {
	body := append([]byte(nil), c.Body()...) // own copy
	go process(body) // safe: independent memory
	return c.SendStatus(200)
})

// For contrast, net/http is safe by default:
// b, _ := io.ReadAll(r.Body) // r.Body is per-request, not pooled

