package solution

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

// Mount on the stdlib mux.
func TestOnStdlibMux(t *testing.T) {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /users/{id}", GetUser)
	rr := httptest.NewRecorder()
	mux.ServeHTTP(rr, httptest.NewRequest("GET", "/users/42", nil))
	if rr.Body.String() != "user 42" {
		t.Fatalf("stdlib mux: got %q want %q", rr.Body.String(), "user 42")
	}
}

// Simulate Chi-style routing by setting the path value the way Chi v5 does.
func TestOnChiLike(t *testing.T) {
	req := httptest.NewRequest("GET", "/users/7", nil)
	req.SetPathValue("id", "7") // Chi v5 populates r.PathValue
	rr := httptest.NewRecorder()
	GetUser(rr, req)
	if rr.Body.String() != "user 7" {
		t.Fatalf("chi-like: got %q want %q", rr.Body.String(), "user 7")
	}
}

