package solution

import "net/http"

// WithHeader is a portable func(http.Handler) http.Handler middleware.
// It works on the stdlib mux, Chi (r.Use), gorilla, and any net/http router.
func WithHeader(key, value string) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set(key, value) // set before writing the body
			next.ServeHTTP(w, r)       // delegate inward
		})
	}
}

