// Simulate Chi's r.Use: Chi calls middleware with the exact same signature.
func TestChiUse(t *testing.T) {
	var mw func(http.Handler) http.Handler = WithHeader("X-App", "chi")
	h := mw(final()) // this is exactly what r.Use does internally
	rr := httptest.NewRecorder()
	h.ServeHTTP(rr, httptest.NewRequest("GET", "/", nil))
	if rr.Header().Get("X-App") != "chi" {
		t.Fatalf("chi: header not set, got %q", rr.Header().Get("X-App"))
