// Rewrite as a NATIVE Fiber middleware (fasthttp world).
func Logging(c *fiber.Ctx) error {
	start := time.Now()
	err := c.Next() // call the rest of the chain
	log.Printf("%s %s %s", c.Method(), c.Path(), time.Since(start))
	return err
}

func main() {
	app := fiber.New()
	app.Use(Logging) // now the signature matches func(*fiber.Ctx) error
	// or: app.Use(logger.New()) using Fiber's built-in middleware
	app.Get("/users/:id", func(c *fiber.Ctx) error {
		return c.SendString("user " + c.Params("id"))
	})
	app.Listen(":8080")
}

type Middleware func(http.Handler) http.Handler

// Chain composes middleware so the FIRST argument is the OUTERMOST layer.
// Chain(A, B, C)(h) == A(B(C(h))).
func Chain(mws ...Middleware) Middleware {
	return func(h http.Handler) http.Handler {
		// Wrap from the innermost outward so mws[0] ends up outermost.
		for i := len(mws) - 1; i >= 0; i-- {
			h = mws[i](h)
		}
		return h
	}
}

// Health is a portable net/http handler.
func Health(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

// Test drives it through the Go 1.22 mux with httptest (no server).
func TestHealth(t *testing.T) {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", Health)

	rr := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/healthz", nil)
	mux.ServeHTTP(rr, req)

	if rr.Code != http.StatusOK {
		t.Fatalf("status: got %d want 200", rr.Code)
	}
	if rr.Body.String() != "ok" {
		t.Fatalf("body: got %q want %q", rr.Body.String(), "ok")
	}
}
